create extension if not exists pgcrypto;
create table public.import_batches(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,file_name text not null,file_type text not null check(file_type in('orders','shipments','tolerances')),row_count integer not null default 0,status text not null default 'processing',created_at timestamptz not null default now());
create table public.orders(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,import_batch_id uuid references public.import_batches(id),order_no text not null,product_no text not null default '',customer text,product_name text,quantity numeric,order_value numeric,currency text,created_at_source timestamptz,customer_date timestamptz,status text,updated_at timestamptz not null default now(),unique(user_id,order_no,product_no));
create table public.shipments(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,import_batch_id uuid references public.import_batches(id),document_no text not null,order_ref text not null,order_no text,product_name text not null default '',shipped_quantity numeric,loading_date timestamptz,customer text,updated_at timestamptz not null default now(),unique(user_id,document_no,order_ref,product_name));
create table public.tolerances(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,import_batch_id uuid references public.import_batches(id),customer text not null,volume_band text not null default '-',shortage_pct numeric,surplus_pct numeric,notes text,updated_at timestamptz not null default now(),unique(user_id,customer,volume_band));
alter table public.import_batches enable row level security;alter table public.orders enable row level security;alter table public.shipments enable row level security;alter table public.tolerances enable row level security;
create policy own_batches on public.import_batches for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy own_orders on public.orders for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy own_shipments on public.shipments for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy own_tolerances on public.tolerances for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create or replace view public.order_fulfilment with (security_invoker=true) as select o.user_id,o.order_no,max(o.customer) customer,sum(coalesce(o.quantity,0)) ordered_quantity,coalesce(s.shipped_quantity,0) shipped_quantity,greatest(sum(coalesce(o.quantity,0))-coalesce(s.shipped_quantity,0),0) short_quantity,case when sum(coalesce(o.quantity,0))=0 then null else coalesce(s.shipped_quantity,0)/sum(o.quantity) end fulfilment_rate,min(o.currency) currency,sum(o.order_value) order_value,max(o.status) status,min(o.created_at_source) order_date,max(s.last_shipment) last_shipment from public.orders o left join(select user_id,order_no,sum(coalesce(shipped_quantity,0)) shipped_quantity,max(loading_date) last_shipment from public.shipments group by user_id,order_no)s on s.user_id=o.user_id and s.order_no=o.order_no group by o.user_id,o.order_no,s.shipped_quantity;
grant select on public.order_fulfilment to authenticated;
create or replace function public.data_quality_summary() returns jsonb language sql security invoker set search_path=public as $$select jsonb_build_object('shipments_without_order',(select count(*) from shipments s where not exists(select 1 from orders o where o.user_id=s.user_id and o.order_no=s.order_no)),'orders_without_currency',(select count(*) from orders where order_value is not null and coalesce(currency,'')=''),'missing_order_quantity',(select count(*) from orders where quantity is null),'missing_shipment_quantity',(select count(*) from shipments where shipped_quantity is null));$$;
grant execute on function public.data_quality_summary() to authenticated;
